// Le o parametro ?mes=YYYY-MM da query (default: mes atual)
const q = $input.first().json.query || {};
const pad = (n) => String(n).padStart(2, '0');

let mes = String(q.mes || '').trim();
if (!/^\d{4}-\d{2}$/.test(mes)) {
  const agora = new Date();
  mes = `${agora.getFullYear()}-${pad(agora.getMonth() + 1)}`;
}

const [ano, m] = mes.split('-').map(Number);

// Intervalo [primeiro dia do mes, primeiro dia do mes seguinte), fuso -03:00
const timeMin = `${ano}-${pad(m)}-01T00:00:00-03:00`;
const proximoAno = m === 12 ? ano + 1 : ano;
const proximoMes = m === 12 ? 1 : m + 1;
const timeMax = `${proximoAno}-${pad(proximoMes)}-01T00:00:00-03:00`;

// Todos os dias do mes (para o front saber o que e livre)
const totalDias = new Date(ano, m, 0).getDate();
const todos = [];
for (let d = 1; d <= totalDias; d++) {
  todos.push(`${ano}-${pad(m)}-${pad(d)}`);
}

return [{ json: { mes, timeMin, timeMax, todos } }];

// Extrai os dias ocupados (eventos) e os bloqueados (fim de semana)
const cfg = $('Calcular Mes').first().json;
const ocupados = new Set();

for (const item of $input.all()) {
  const ev = item.json || {};
  const start = ev.start || ev.startDate || {};
  const bruto = (typeof start === 'object') ? (start.date || start.dateTime) : start;
  if (!bruto) continue;
  ocupados.add(String(bruto).substring(0, 10));
}

// Dias em que NAO se trabalha: 0 = domingo, 6 = sabado
const DIAS_FECHADOS = [0, 6];
const bloqueados = cfg.todos.filter(function (d) {
  const p = d.split('-').map(Number);
  const wd = new Date(Date.UTC(p[0], p[1] - 1, p[2])).getUTCDay();
  return DIAS_FECHADOS.indexOf(wd) >= 0;
});

const diasOcupados = Array.from(ocupados).sort();
const diasLivres = cfg.todos.filter(function (d) {
  return !ocupados.has(d) && bloqueados.indexOf(d) < 0;
});

return [{ json: { mes: cfg.mes, diasOcupados: diasOcupados, diasBloqueados: bloqueados, diasLivres: diasLivres } }];
